#!/usr/bin/env node
/**
 * gen-routes.mjs — one thin .astro route per surface, generated from uis.yaml.
 *
 * Why files and not one [...slug].astro: Astro resolves hydration directives
 * (client:load and friends) at compile time from a static import, so a route
 * built from import.meta.glob can be server-rendered but not hydrated. Generating
 * one file per board keeps a static import, keeps per-route code splitting, and
 * makes the hydration mode a YAML decision.
 *
 * Generated files carry a DO NOT EDIT header. Re-run after editing uis.yaml.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import YAML from "yaml";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const CONFIG = path.join(root, "uis.yaml");
const cfg = YAML.parse(fs.readFileSync(CONFIG, "utf8"));

const HYDRATION = new Set(["static", "client:load", "client:idle", "client:visible"]);
const HEADER = `// Generated by scripts/gen-routes.mjs from uis.yaml — do not edit by hand.\n`;

const written = new Set();

function emit(entry) {
  if (!entry.route || !entry.file) return;
  const dir = entry.route.startsWith("/ds/") ? "ds" : "ui";
  const name = entry.route.replace(/^\/(ui|ds)\//, "");
  const target = path.join(root, "src/pages", dir, `${name}.astro`);
  const hydration = HYDRATION.has(entry.hydration) ? entry.hydration : "client:load";
  const tag = hydration === "static" ? "<Page />" : `<Page ${hydration} />`;
  const importName = path.basename(entry.file, ".tsx");
  const body = `---
import Board from "@/layouts/Board.astro";
import Page from "${entry.file.replace(/^src\//, "@/").replace(/\.tsx$/, "")}";
${HEADER}const title = ${JSON.stringify(`${entry.id} ${entry.title}`)};
const pipelineStep = ${JSON.stringify(entry.pipeline ?? null)};
---

<Board title={\`\${title} — HerStory\`} id="${entry.id}" slug="${entry.route}" pipelineStep={pipelineStep}>
  <div data-board-root data-ui-id="${entry.id}">
    ${tag}
  </div>
</Board>
`;
  fs.mkdirSync(path.dirname(target), { recursive: true });
  written.add(target);
  void importName;
  return { target, body };
}

const check = process.argv.includes("--check");
const stale = [];
for (const entry of cfg.ui) {
  const res = emit(entry);
  if (!res) continue;
  const current = fs.existsSync(res.target) ? fs.readFileSync(res.target, "utf8") : null;
  if (check) {
    if (current !== res.body) stale.push(path.relative(root, res.target));
  } else {
    fs.writeFileSync(res.target, res.body);
  }
}
if (check) {
  if (stale.length) {
    console.error(`gen-routes --check: ${stale.length} route(s) out of date`);
    for (const f of stale.slice(0, 20)) console.error(`  ${f}`);
    process.exit(1);
  }
  console.log(`gen-routes --check: ${written.size} routes current`);
  process.exit(0);
}

/* prune routes whose surface disappeared, but never touch hand-written pages */
for (const dir of ["ui", "ds"]) {
  const abs = path.join(root, "src/pages", dir);
  if (!fs.existsSync(abs)) continue;
  for (const file of fs.readdirSync(abs)) {
    if (!file.endsWith(".astro")) continue;
    const p = path.join(abs, file);
    if (!written.has(p) && fs.readFileSync(p, "utf8").includes("Generated by scripts/gen-routes.mjs")) {
      fs.rmSync(p);
    }
  }
}

const counts = { static: 0, hydrated: 0 };
for (const entry of cfg.ui) {
  if (entry.hydration === "static") counts.static++;
  else if (entry.route && entry.file) counts.hydrated++;
}
console.log(`gen-routes: ${written.size} routes (${counts.hydrated} hydrated, ${counts.static} static)`);
